'use strict';

const { InvalidQuantityError, ProductNotFoundError } = require('./errors');

class Cart {
  constructor() {
    this.items = new Map(); // productId -> quantity
  }

  add(product, quantity = 1) {
    if (!product || typeof product.id === 'undefined') {
      throw new ProductNotFoundError('Product is required');
    }
    const qty = Number(quantity);
    if (!Number.isInteger(qty) || qty <= 0) {
      throw new InvalidQuantityError(`Invalid quantity: ${quantity}`);
    }
    const current = this.items.get(product.id) || 0;
    this.items.set(product.id, current + qty);
    return this.items.get(product.id);
  }

  update(productId, quantity) {
    if (!this.items.has(productId)) {
      throw new ProductNotFoundError(`Product ${productId} is not in the cart`);
    }
    const qty = Number(quantity);
    if (!Number.isInteger(qty) || qty <= 0) {
      throw new InvalidQuantityError(`Invalid quantity: ${quantity}`);
    }
    this.items.set(productId, qty);
    return qty;
  }

  remove(productId) {
    if (!this.items.has(productId)) {
      throw new ProductNotFoundError(`Product ${productId} is not in the cart`);
    }
    this.items.delete(productId);
    return true;
  }

  getQuantity(productId) {
    return this.items.get(productId) || 0;
  }

  getItems() {
    return Array.from(this.items.entries()).map(([productId, quantity]) => ({
      productId,
      quantity,
    }));
  }

  isEmpty() {
    return this.items.size === 0;
  }

  clear() {
    this.items.clear();
  }

  calculateTotals(catalog) {
    let subtotal = 0;
    const lines = [];
    for (const [productId, quantity] of this.items.entries()) {
      const product = catalog.getProduct(productId);
      if (!product) {
        throw new ProductNotFoundError(`Product ${productId} does not exist`);
      }
      const lineTotal = product.price * quantity;
      subtotal += lineTotal;
      lines.push({
        productId,
        name: product.name,
        price: product.price,
        quantity,
        lineTotal,
      });
    }
    return { subtotal, total: subtotal, lines };
  }
}

module.exports = { Cart };

'use strict';

const { InvalidProductDataError, DuplicateProductError, ProductNotFoundError } = require('./errors');

function createCatalog() {
  return new Catalog();
}

function createProduct(catalog, data) {
  return catalog.createProduct(data);
}

function getProduct(catalog, id) {
  return catalog.getProduct(id);
}

function listProducts(catalog) {
  return catalog.listProducts();
}

function updateProduct(catalog, id, updates) {
  return catalog.updateProduct(id, updates);
}

class Catalog {
  constructor() {
    this.products = new Map();
  }

  createProduct({ id, name, description = '', price, quantity }) {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new ValidationError('Product ID must be a non-empty string.');
    }
    if (this.products.has(id)) {
      throw new DuplicateProductError(`Product with ID '${id}' already exists.`);
    }
    if (typeof name !== 'string' || name.trim() === '') {
      throw new ValidationError('Product name must be a non-empty string.');
    }
    if (typeof description !== 'string') {
      throw new ValidationError('Product description must be a string.');
    }
    if (typeof price !== 'number' || !Number.isFinite(price) || price < 0) {
      throw new ValidationError('Product price must be a non-negative finite number.');
    }
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError('Product quantity must be a non-negative integer.');
    }

    const product = {
      id,
      name: name.trim(),
      description,
      price,
      quantity,
    };
    this.products.set(id, product);
    return product;
  }

  getProduct(id) {
    const product = this.products.get(id);
    if (!product) {
      throw new ProductNotFoundError(`Product with ID '${id}' was not found.`);
    }
    return product;
  }

  hasProduct(id) {
    return this.products.has(id);
  }

  listProducts() {
    return Array.from(this.products.values());
  }

  updateProduct(id, updates = {}) {
    const product = this.getProduct(id);
    const allowed = ['name', 'description', 'price', 'quantity'];
    for (const key of Object.keys(updates)) {
      if (!allowed.includes(key)) {
        throw new ValidationError(`Cannot update unknown product field '${key}'.`);
      }
    }

    if (updates.name !== undefined) {
      if (typeof updates.name !== 'string' || updates.name.trim() === '') {
        throw new ValidationError('Product name must be a non-empty string.');
      }
      product.name = updates.name.trim();
    }
    if (updates.description !== undefined) {
      if (typeof updates.description !== 'string') {
        throw new ValidationError('Product description must be a string.');
      }
      product.description = updates.description;
    }
    if (updates.price !== undefined) {
      if (typeof updates.price !== 'number' || !Number.isFinite(updates.price) || updates.price < 0) {
        throw new ValidationError('Product price must be a non-negative finite number.');
      }
      product.price = updates.price;
    }
    if (updates.quantity !== undefined) {
      if (!Number.isInteger(updates.quantity) || updates.quantity < 0) {
        throw new ValidationError('Product quantity must be a non-negative integer.');
      }
      product.quantity = updates.quantity;
    }

    return product;
  }
}

module.exports = { Catalog };

'use strict';

const { EmptyCartError, CheckoutError } = require('./errors');

class CheckoutService {
  constructor(catalog, inventory, orders) {
    this.catalog = catalog;
    this.inventory = inventory;
    this.orders = orders;
  }

  checkout(cart) {
    if (cart.isEmpty()) {
      throw new EmptyCartError('Cannot checkout an empty cart');
    }

    const items = cart.getItems();
    const totals = cart.calculateTotals(this.catalog);

    try {
      this.inventory.deduct(items);
    } catch (err) {
      throw new CheckoutError(`Checkout failed: ${err.message}`);
    }

    const order = this.orders.createOrder(items, totals.total);
    cart.clear();
    return order;
  }
}

module.exports = { CheckoutService };

'use strict';

/**
 * Shared error types for OrderFlow.
 */

class OrderFlowError extends Error {
  constructor(message, code = 'ORDERFLOW_ERROR') {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ProductNotFoundError extends OrderFlowError {
  constructor(productId) {
    super(`Product not found: ${productId}`, 'PRODUCT_NOT_FOUND');
    this.productId = productId;
  }
}

class DuplicateProductError extends OrderFlowError {
  constructor(productId) {
    super(`Product already exists: ${productId}`, 'DUPLICATE_PRODUCT');
    this.productId = productId;
  }
}

class InvalidProductDataError extends OrderFlowError {
  constructor(message) {
    super(message, 'INVALID_PRODUCT_DATA');
  }
}

class InvalidQuantityError extends OrderFlowError {
  constructor(message = 'Quantity must be a positive integer') {
    super(message, 'INVALID_QUANTITY');
  }
}

class InsufficientInventoryError extends OrderFlowError {
  constructor(productId, requested, available) {
    super(
      `Insufficient inventory for ${productId}: requested ${requested}, available ${available}`,
      'INSUFFICIENT_INVENTORY'
    );
    this.productId = productId;
    this.requested = requested;
    this.available = available;
  }
}

class OrderNotFoundError extends OrderFlowError {
  constructor(orderId) {
    super(`Order not found: ${orderId}`, 'ORDER_NOT_FOUND');
    this.orderId = orderId;
  }
}

class InvalidOrderStateError extends OrderFlowError {
  constructor(orderId, status) {
    super(`Order ${orderId} cannot be cancelled from status ${status}`, 'INVALID_ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  OrderFlowError,
  ProductNotFoundError,
  DuplicateProductError,
  InvalidProductDataError,
  InvalidQuantityError,
  InsufficientInventoryError,
  OrderNotFoundError,
  InvalidOrderStateError,
};

'use strict';

const { InsufficientInventoryError, ProductNotFoundError } = require('./errors');

class InventoryManager {
  constructor(catalog) {
    this.catalog = catalog;
  }

  checkAvailability(items) {
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      if (!product) {
        throw new ProductNotFoundError(`Product ${item.productId} does not exist`);
      }
      if (product.inventory < item.quantity) {
        throw new InsufficientInventoryError(
          `Insufficient inventory for ${product.name}: requested ${item.quantity}, available ${product.inventory}`
        );
      }
    }
    return true;
  }

  deduct(items) {
    this.checkAvailability(items);
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      product.inventory -= item.quantity;
    }
    return true;
  }

  restore(items) {
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      if (product) {
        product.inventory += item.quantity;
      }
    }
    return true;
  }
}

module.exports = { InventoryManager };

'use strict';

const { OrderNotFoundError, InvalidOrderStateError } = require('./errors');

class OrderManager {
  constructor() {
    this.orders = new Map();
    this.nextId = 1;
  }

  createOrder(items, total, timestamp = new Date()) {
    const id = `ORD-${String(this.nextId).padStart(5, '0')}`;
    this.nextId += 1;
    const order = {
      id,
      items: items.map((item) => ({ ...item })),
      total,
      timestamp,
      status: 'completed',
      cancelledAt: null,
    };
    this.orders.set(id, order);
    return order;
  }

  getOrder(id) {
    const order = this.orders.get(id);
    if (!order) {
      throw new OrderNotFoundError(`Order ${id} not found`);
    }
    return order;
  }

  listOrders() {
    return Array.from(this.orders.values());
  }

  cancelOrder(id, timestamp = new Date()) {
    const order = this.getOrder(id);
    if (order.status === 'cancelled') {
      throw new InvalidOrderStateError(`Order ${id} is already cancelled`);
    }
    order.status = 'cancelled';
    order.cancelledAt = timestamp;
    return order;
  }
}

module.exports = { OrderManager };

'use strict';

/**
 * Reporting module for OrderFlow.
 * Works against the in-memory order store and catalog.
 */

/**
 * @param {Array<object>} orders
 * @returns {number} total sales from completed orders
 */
function totalSales(orders) {
  return orders
    .filter((order) => order.status === 'completed')
    .reduce((sum, order) => sum + order.total, 0);
}

/**
 * @param {Array<object>} orders
 * @returns {{completed: number, cancelled: number}}
 */
function orderCounts(orders) {
  return orders.reduce(
    (counts, order) => {
      if (order.status === 'completed') counts.completed += 1;
      if (order.status === 'cancelled') counts.cancelled += 1;
      return counts;
    },
    { completed: 0, cancelled: 0 }
  );
}

/**
 * Identify best-selling products from completed orders.
 * @param {Array<object>} orders
 * @returns {Array<{productId: string, quantity: number}>} sorted descending by quantity
 */
function bestSellingProducts(orders) {
  const totals = new Map();

  for (const order of orders) {
    if (order.status !== 'completed') continue;
    for (const item of order.items) {
      const current = totals.get(item.productId) || 0;
      totals.set(item.productId, current + item.quantity);
    }
  }

  return Array.from(totals, ([productId, quantity]) => ({ productId, quantity }))
    .sort((a, b) => b.quantity - a.quantity);
}

/**
 * Report remaining inventory for each product.
 * @param {Array<object>} products
 * @returns {Array<{productId: string, name: string, quantity: number}>}
 */
function remainingInventory(products) {
  return products.map((product) => ({
    productId: product.id,
    name: product.name,
    quantity: product.inventory,
  }));
}

/**
 * Build a complete sales report.
 * @param {Array<object>} orders
 * @param {Array<object>} products
 * @returns {object}
 */
function generateReport(orders, products) {
  return {
    totalSales: totalSales(orders),
    orderCounts: orderCounts(orders),
    bestSellingProducts: bestSellingProducts(orders),
    remainingInventory: remainingInventory(products),
  };
}

module.exports = {
  totalSales,
  orderCounts,
  bestSellingProducts,
  remainingInventory,
  generateReport,
};

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const { createCatalog, createProduct } = require('../src/catalog');
const { createCart, addToCart, updateQuantity, removeFromCart, cartTotals } = require('../src/cart');
const { InvalidQuantityError, ProductNotFoundError } = require('../src/errors');

function sampleCatalog() {
  const catalog = createCatalog();
  createProduct(catalog, {
    id: 'p1',
    name: 'Widget',
    description: 'A widget',
    price: 10,
    inventory: 20,
  });
  createProduct(catalog, {
    id: 'p2',
    name: 'Gadget',
    description: 'A gadget',
    price: 5.5,
    inventory: 15,
  });
  return catalog;
}

test('adds products to a cart', () => {
  const catalog = sampleCatalog();
  const cart = createCart();
  addToCart(cart, catalog, 'p1', 2);
  addToCart(cart, catalog, 'p2', 1);

  assert.equal(cart.items.length, 2);
  assert.equal(cart.items[0].productId, 'p1');
  assert.equal(cart.items[0].quantity, 2);
});

test('calculates subtotals and totals', () => {
  const catalog = sampleCatalog();
  const cart = createCart();
  addToCart(cart, catalog, 'p1', 2);
  addToCart(cart, catalog, 'p2', 3);

  const totals = cartTotals(cart);
  assert.equal(totals.subtotal, 36.5);
  assert.equal(totals.total, 36.5);
});

test('updates product quantities', () => {
  const catalog = sampleCatalog();
  const cart = createCart();
  addToCart(cart, catalog, 'p1', 2);
  updateQuantity(cart, 'p1', 5);

  assert.equal(cart.items[0].quantity, 5);
});

test('removes products from cart', () => {
  const catalog = sampleCatalog();
  const cart = createCart();
  addToCart(cart, catalog, 'p1', 2);
  addToCart(cart, catalog, 'p2', 1);
  removeFromCart(cart, 'p1');

  assert.equal(cart.items.length, 1);
  assert.equal(cart.items[0].productId, 'p2');
});

test('rejects invalid quantities', () => {
  const catalog = sampleCatalog();
  const cart = createCart();

  assert.throws(() => addToCart(cart, catalog, 'p1', 0), InvalidQuantityError);
  assert.throws(() => addToCart(cart, catalog, 'p1', -1), InvalidQuantityError);
  assert.throws(() => addToCart(cart, catalog, 'p1', 1.5), InvalidQuantityError);
});

test('rejects nonexistent products', () => {
  const catalog = sampleCatalog();
  const cart = createCart();

  assert.throws(() => addToCart(cart, catalog, 'missing', 1), ProductNotFoundError);
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const {
  createCatalog,
  createProduct,
  getProduct,
  listProducts,
  updateProduct,
} = require('../src/catalog');
const {
  DuplicateProductError,
  InvalidProductDataError,
  ProductNotFoundError,
} = require('../src/errors');

test('creates and retrieves a product', () => {
  const catalog = createCatalog();
  const product = createProduct(catalog, {
    id: 'p1',
    name: 'Widget',
    description: 'A useful widget',
    price: 19.99,
    inventory: 10,
  });

  assert.equal(product.id, 'p1');
  assert.equal(getProduct(catalog, 'p1').name, 'Widget');
  assert.equal(listProducts(catalog).length, 1);
});

test('rejects duplicate product IDs', () => {
  const catalog = createCatalog();
  createProduct(catalog, {
    id: 'p1',
    name: 'Widget',
    description: 'A useful widget',
    price: 19.99,
    inventory: 10,
  });

  assert.throws(
    () =>
      createProduct(catalog, {
        id: 'p1',
        name: 'Another Widget',
        description: 'Duplicate',
        price: 5,
        inventory: 1,
      }),
    DuplicateProductError
  );
});

test('rejects invalid price', () => {
  const catalog = createCatalog();
  assert.throws(
    () =>
      createProduct(catalog, {
        id: 'p1',
        name: 'Widget',
        description: 'Bad price',
        price: -1,
        inventory: 10,
      }),
    InvalidProductDataError
  );
});

test('rejects invalid inventory quantity', () => {
  const catalog = createCatalog();
  assert.throws(
    () =>
      createProduct(catalog, {
        id: 'p1',
        name: 'Widget',
        description: 'Bad inventory',
        price: 10,
        inventory: -5,
      }),
    InvalidProductDataError
  );
});

test('updates product information', () => {
  const catalog = createCatalog();
  createProduct(catalog, {
    id: 'p1',
    name: 'Widget',
    description: 'Old description',
    price: 10,
    inventory: 5,
  });

  const updated = updateProduct(catalog, 'p1', {
    name: 'Super Widget',
    price: 15,
    inventory: 8,
  });

  assert.equal(updated.name, 'Super Widget');
  assert.equal(updated.price, 15);
  assert.equal(updated.inventory, 8);
  assert.equal(getProduct(catalog, 'p1').description, 'Old description');
});

test('throws when retrieving a missing product', () => {
  const catalog = createCatalog();
  assert.throws(() => getProduct(catalog, 'missing'), ProductNotFoundError);
});

const test = require('node:test');
const assert = require('node:assert/strict');

const { Catalog } = require('../src/catalog');
const { Cart } = require('../src/cart');
const { Inventory } = require('../src/inventory');
const { Orders } = require('../src/orders');
const { Checkout } = require('../src/checkout');

test('successful checkout creates an order and deducts inventory', () => {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);

  catalog.createProduct({ id: 'p1', name: 'Widget', price: 10, quantity: 5 });
  inventory.setStock('p1', 5);

  const cart = new Cart();
  cart.addItem('p1', 2);

  const order = checkout.process(cart);

  assert.equal(order.status, 'completed');
  assert.equal(order.total, 20);
  assert.equal(inventory.getStock('p1'), 3);
  assert.equal(orders.getOrder(order.id), order);
});

test('checkout rejects insufficient inventory without deducting stock', () => {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);

  catalog.createProduct({ id: 'p2', name: 'Gadget', price: 5, quantity: 1 });
  inventory.setStock('p2', 1);

  const cart = new Cart();
  cart.addItem('p2', 3);

  assert.throws(() => checkout.process(cart), /insufficient|stock/i);
  assert.equal(inventory.getStock('p2'), 1);
  assert.equal(orders.count(), 0);
});

test('checkout rejects unknown products', () => {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);

  const cart = new Cart();
  cart.addItem('missing', 1);

  assert.throws(() => checkout.process(cart), /not found|unknown|exist/i);
  assert.equal(orders.count(), 0);
});

test('checkout preserves inventory when order creation fails', () => {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);

  catalog.createProduct({ id: 'p3', name: 'Thing', price: 7, quantity: 4 });
  inventory.setStock('p3', 4);

  const cart = new Cart();
  cart.addItem('p3', 2);

  const originalCreate = orders.createOrder.bind(orders);
  orders.createOrder = () => {
    throw new Error('forced order failure');
  };

  assert.throws(() => checkout.process(cart), /forced order failure/);
  assert.equal(inventory.getStock('p3'), 4);

  orders.createOrder = originalCreate;
});

test('checkout generates unique order ids', () => {
  const catalog = new Catalog();
  const inventory = new Inventory();
  const orders = new Orders();
  const checkout = new Checkout(catalog, inventory, orders);

  catalog.createProduct({ id: 'p4', name: 'Item', price: 3, quantity: 10 });
  inventory.setStock('p4', 10);

  const ids = new Set();
  for (let i = 0; i < 5; i += 1) {
    const cart = new Cart();
    cart.addItem('p4', 1);
    const order = checkout.process(cart);
    ids.add(order.id);
  }

  assert.equal(ids.size, 5);
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const { createCatalog, createProduct, getProduct } = require('../src/catalog');
const {
  checkInventory,
  deductInventory,
  restoreInventory,
} = require('../src/inventory');
const { InsufficientInventoryError, ProductNotFoundError } = require('../src/errors');

function sampleCatalog() {
  const catalog = createCatalog();
  createProduct(catalog, {
    id: 'p1',
    name: 'Widget',
    description: 'A widget',
    price: 10,
    inventory: 5,
  });
  return catalog;
}

test('checks inventory successfully', () => {
  const catalog = sampleCatalog();
  assert.doesNotThrow(() => checkInventory(catalog, [{ productId: 'p1', quantity: 3 }]));
});

test('rejects purchases exceeding available stock', () => {
  const catalog = sampleCatalog();
  assert.throws(
    () => checkInventory(catalog, [{ productId: 'p1', quantity: 6 }]),
    InsufficientInventoryError
  );
});

test('deducts inventory', () => {
  const catalog = sampleCatalog();
  deductInventory(catalog, [{ productId: 'p1', quantity: 3 }]);
  assert.equal(getProduct(catalog, 'p1').inventory, 2);
});

test('restores inventory', () => {
  const catalog = sampleCatalog();
  deductInventory(catalog, [{ productId: 'p1', quantity: 3 }]);
  restoreInventory(catalog, [{ productId: 'p1', quantity: 3 }]);
  assert.equal(getProduct(catalog, 'p1').inventory, 5);
});

test('rejects inventory operations for missing products', () => {
  const catalog = sampleCatalog();
  assert.throws(
    () => checkInventory(catalog, [{ productId: 'missing', quantity: 1 }]),
    ProductNotFoundError
  );
});

