'use strict';

const { ValidationError, NotFoundError } = require('./errors');

class Cart {
  constructor(catalog) {
    if (!catalog || typeof catalog.getProduct !== 'function') {
      throw new TypeError('Cart requires a catalog with getProduct()');
    }
    this.catalog = catalog;
    this.items = new Map();
  }

  addItem(productId, quantity = 1) {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }
    const product = this.catalog.getProduct(productId);
    const current = this.items.get(productId);
    const nextQuantity = (current ? current.quantity : 0) + quantity;
    this.items.set(productId, {
      productId,
      name: product.name,
      price: product.price,
      quantity: nextQuantity,
    });
    return this.getItem(productId);
  }

  updateQuantity(productId, quantity) {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }
    if (!this.items.has(productId)) {
      throw new NotFoundError(`Product "${productId}" is not in the cart`);
    }
    const product = this.catalog.getProduct(productId);
    this.items.set(productId, {
      productId,
      name: product.name,
      price: product.price,
      quantity,
    });
    return this.getItem(productId);
  }

  removeItem(productId) {
    if (!this.items.has(productId)) {
      throw new NotFoundError(`Product "${productId}" is not in the cart`);
    }
    this.items.delete(productId);
    return true;
  }

  getItem(productId) {
    const item = this.items.get(productId);
    if (!item) {
      throw new NotFoundError(`Product "${productId}" is not in the cart`);
    }
    return { ...item };
  }

  listItems() {
    return Array.from(this.items.values()).map((item) => ({ ...item }));
  }

  subtotal() {
    return this.listItems().reduce((sum, item) => sum + item.price * item.quantity, 0);
  }

  total() {
    return this.subtotal();
  }

  isEmpty() {
    return this.items.size === 0;
  }

  clear() {
    this.items.clear();
  }
}

module.exports = { Cart };

'use strict';

const {
  ValidationError,
  NotFoundError,
  DuplicateError,
} = require('./errors');

class Catalog {
  constructor() {
    this.products = new Map();
  }

  createProduct({ id, name, description = '', price, quantity = 0 }) {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new ValidationError('Product id must be a non-empty string');
    }
    if (this.products.has(id)) {
      throw new DuplicateError(`Product with id "${id}" already exists`);
    }
    if (typeof name !== 'string' || name.trim() === '') {
      throw new ValidationError('Product name must be a non-empty string');
    }
    if (typeof description !== 'string') {
      throw new ValidationError('Product description must be a string');
    }
    if (!Number.isFinite(price) || price < 0) {
      throw new ValidationError('Product price must be a non-negative number');
    }
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError('Product quantity must be a non-negative integer');
    }

    const product = {
      id,
      name: name.trim(),
      description,
      price,
      quantity,
    };
    this.products.set(id, product);
    return { ...product };
  }

  getProduct(id) {
    const product = this.products.get(id);
    if (!product) {
      throw new NotFoundError(`Product "${id}" not found`);
    }
    return { ...product };
  }

  listProducts() {
    return Array.from(this.products.values()).map((product) => ({ ...product }));
  }

  updateProduct(id, updates = {}) {
    const product = this.products.get(id);
    if (!product) {
      throw new NotFoundError(`Product "${id}" not found`);
    }

    const allowed = ['name', 'description', 'price', 'quantity'];
    for (const key of Object.keys(updates)) {
      if (!allowed.includes(key)) {
        throw new ValidationError(`Cannot update unknown field "${key}"`);
      }
    }

    if (updates.name !== undefined) {
      if (typeof updates.name !== 'string' || updates.name.trim() === '') {
        throw new ValidationError('Product name must be a non-empty string');
      }
      product.name = updates.name.trim();
    }

    if (updates.description !== undefined) {
      if (typeof updates.description !== 'string') {
        throw new ValidationError('Product description must be a string');
      }
      product.description = updates.description;
    }

    if (updates.price !== undefined) {
      if (!Number.isFinite(updates.price) || updates.price < 0) {
        throw new ValidationError('Product price must be a non-negative number');
      }
      product.price = updates.price;
    }

    if (updates.quantity !== undefined) {
      if (!Number.isInteger(updates.quantity) || updates.quantity < 0) {
        throw new ValidationError('Product quantity must be a non-negative integer');
      }
      product.quantity = updates.quantity;
    }

    return { ...product };
  }

  hasProduct(id) {
    return this.products.has(id);
  }
}

module.exports = { Catalog };

'use strict';

const { OrderStore } = require('./orders');
const { InventoryManager } = require('./inventory');
const { InsufficientInventoryError, InvalidStateError } = require('./errors');

class CheckoutService {
  /**
   * @param {OrderStore} orderStore
   * @param {InventoryManager} inventory
   */
  constructor(orderStore, inventory) {
    this.orderStore = orderStore;
    this.inventory = inventory;
  }

  /**
   * Convert a valid cart into an order.
   * Inventory is checked and deducted atomically from the caller's perspective:
   * if any item is unavailable, no inventory is changed.
   *
   * @param {import('./cart').Cart} cart
   * @param {object} [options]
   * @param {string} [options.customerId]
   * @returns {object} created order
   */
  checkout(cart, options = {}) {
    if (!cart || typeof cart.listItems !== 'function') {
      throw new InvalidStateError('A valid cart is required for checkout.');
    }

    const items = cart.listItems();
    if (items.length === 0) {
      throw new InvalidStateError('Cannot check out an empty cart.');
    }

    // Validate every line before touching inventory.
    for (const item of items) {
      this.inventory.assertAvailable(item.productId, item.quantity);
    }

    // All checks passed: deduct inventory, then create the order.
    for (const item of items) {
      this.inventory.deduct(item.productId, item.quantity);
    }

    const order = this.orderStore.createOrder(items, {
      customerId: options.customerId || null,
      total: cart.total(),
    });

    cart.clear();
    return order;
  }

  /**
   * Cancel an order and restore its inventory exactly once.
   *
   * @param {string} orderId
   * @returns {object} cancelled order
   */
  cancelOrder(orderId) {
    const order = this.orderStore.getOrder(orderId);
    if (!order) {
      throw new InvalidStateError(`Order ${orderId} does not exist.`);
    }

    if (order.status === 'cancelled') {
      throw new InvalidStateError(`Order ${orderId} is already cancelled.`);
    }

    const cancelled = this.orderStore.cancelOrder(orderId);
    for (const item of cancelled.items) {
      this.inventory.restore(item.productId, item.quantity);
    }
    return cancelled;
  }
}

module.exports = { CheckoutService };

'use strict';

class OrderFlowError extends Error {
  constructor(message, code = 'ORDERFLOW_ERROR') {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends OrderFlowError {
  constructor(message) {
    super(message, 'VALIDATION_ERROR');
  }
}

class NotFoundError extends OrderFlowError {
  constructor(message) {
    super(message, 'NOT_FOUND');
  }
}

class DuplicateError extends OrderFlowError {
  constructor(message) {
    super(message, 'DUPLICATE');
  }
}

class InsufficientInventoryError extends OrderFlowError {
  constructor(message) {
    super(message, 'INSUFFICIENT_INVENTORY');
  }
}

class InvalidStateError extends OrderFlowError {
  constructor(message) {
    super(message, 'INVALID_STATE');
  }
}

module.exports = {
  OrderFlowError,
  ValidationError,
  NotFoundError,
  DuplicateError,
  InsufficientInventoryError,
  InvalidStateError
};

'use strict';

const { InsufficientInventoryError, NotFoundError } = require('./errors');

class InventoryManager {
  constructor(catalog) {
    if (!catalog || typeof catalog.getProduct !== 'function') {
      throw new TypeError('InventoryManager requires a catalog with getProduct()');
    }
    this.catalog = catalog;
  }

  checkAvailability(items) {
    const shortages = [];
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      if (item.quantity > product.quantity) {
        shortages.push({
          productId: item.productId,
          requested: item.quantity,
          available: product.quantity,
        });
      }
    }
    return shortages;
  }

  assertAvailable(items) {
    const shortages = this.checkAvailability(items);
    if (shortages.length > 0) {
      const detail = shortages
        .map((s) => `${s.productId}: requested ${s.requested}, available ${s.available}`)
        .join('; ');
      throw new InsufficientInventoryError(`Insufficient inventory: ${detail}`);
    }
    return true;
  }

  deduct(items) {
    this.assertAvailable(items);
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      this.catalog.updateProduct(item.productId, {
        quantity: product.quantity - item.quantity,
      });
    }
    return true;
  }

  restore(items) {
    for (const item of items) {
      const product = this.catalog.getProduct(item.productId);
      this.catalog.updateProduct(item.productId, {
        quantity: product.quantity + item.quantity,
      });
    }
    return true;
  }

  getStock(productId) {
    const product = this.catalog.getProduct(productId);
    return product.quantity;
  }

  setStock(productId, quantity) {
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError('Quantity must be a non-negative integer');
    }
    this.catalog.updateProduct(productId, { quantity });
    return this.getStock(productId);
  }
}

module.exports = { InventoryManager };

'use strict';

const { NotFoundError, InvalidStateError } = require('./errors');

class OrderStore {
  constructor() {
    this.orders = new Map();
    this.nextId = 1;
  }

  createOrder({ items, total, timestamp = new Date() }) {
    const id = `ORD-${String(this.nextId).padStart(5, '0')}`;
    this.nextId += 1;
    const order = {
      id,
      items: items.map((item) => ({ ...item })),
      total,
      timestamp: new Date(timestamp),
      status: 'completed',
    };
    this.orders.set(id, order);
    return { ...order, items: order.items.map((item) => ({ ...item })) };
  }

  getOrder(id) {
    const order = this.orders.get(id);
    if (!order) {
      throw new NotFoundError(`Order "${id}" not found`);
    }
    return { ...order, items: order.items.map((item) => ({ ...item })) };
  }

  listOrders() {
    return Array.from(this.orders.values()).map((order) => ({
      ...order,
      items: order.items.map((item) => ({ ...item })),
    }));
  }

  cancelOrder(id) {
    const order = this.orders.get(id);
    if (!order) {
      throw new NotFoundError(`Order "${id}" not found`);
    }
    if (order.status === 'cancelled') {
      throw new InvalidStateError(`Order "${id}" is already cancelled`);
    }
    order.status = 'cancelled';
    return { ...order, items: order.items.map((item) => ({ ...item })) };
  }
}

module.exports = { OrderStore };

'use strict';

class SalesReport {
  /**
   * @param {import('./orders').OrderStore} orderStore
   * @param {import('./inventory').InventoryManager} inventory
   */
  constructor(orderStore, inventory) {
    this.orderStore = orderStore;
    this.inventory = inventory;
  }

  /**
   * Total sales from completed (non-cancelled) orders.
   * @returns {number}
   */
  totalSales() {
    return this.orderStore
      .listOrders()
      .filter((order) => order.status !== 'cancelled')
      .reduce((sum, order) => sum + order.total, 0);
  }

  /**
   * Count orders by status.
   * @returns {{completed: number, cancelled: number, total: number}}
   */
  orderCounts() {
    const orders = this.orderStore.listOrders();
    return {
      completed: orders.filter((order) => order.status === 'completed').length,
      cancelled: orders.filter((order) => order.status === 'cancelled').length,
      total: orders.length,
    };
  }

  /**
   * Best-selling products by quantity across non-cancelled orders.
   * @returns {Array<{productId: string, quantity: number}>}
   */
  bestSellers() {
    const quantities = new Map();

    for (const order of this.orderStore.listOrders()) {
      if (order.status === 'cancelled') continue;
      for (const item of order.items) {
        quantities.set(
          item.productId,
          (quantities.get(item.productId) || 0) + item.quantity
        );
      }
    }

    return Array.from(quantities, ([productId, quantity]) => ({
      productId,
      quantity,
    })).sort((a, b) => b.quantity - a.quantity);
  }

  /**
   * Remaining inventory for every product known to the inventory manager.
   * @returns {Array<{productId: string, quantity: number}>}
   */
  remainingInventory() {
    return this.inventory.listStock();
  }

  /**
   * Full report object.
   * @returns {object}
   */
  generate() {
    return {
      totalSales: this.totalSales(),
      orderCounts: this.orderCounts(),
      bestSellers: this.bestSellers(),
      remainingInventory: this.remainingInventory(),
    };
  }
}

module.exports = { SalesReport };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const { Cart } = require('../src/cart');
const { Catalog } = require('../src/catalog');
const { NotFoundError, ValidationError } = require('../src/errors');

function setup() {
  const catalog = new Catalog();
  catalog.createProduct({
    id: 'p1',
    name: 'Widget',
    price: 10,
    quantity: 20,
  });
  catalog.createProduct({
    id: 'p2',
    name: 'Gadget',
    price: 5.5,
    quantity: 10,
  });
  return { catalog, cart: new Cart(catalog) };
}

test('adds products to a cart', () => {
  const { cart } = setup();
  cart.addItem('p1', 2);
  cart.addItem('p2', 1);

  assert.equal(cart.getItem('p1').quantity, 2);
  assert.equal(cart.getItem('p2').quantity, 1);
  assert.equal(cart.listItems().length, 2);
});

test('rejects nonexistent products', () => {
  const { cart } = setup();
  assert.throws(() => cart.addItem('ghost', 1), NotFoundError);
});

test('rejects invalid quantities', () => {
  const { cart } = setup();
  assert.throws(() => cart.addItem('p1', 0), ValidationError);
  assert.throws(() => cart.addItem('p1', -2), ValidationError);
});

test('updates product quantities', () => {
  const { cart } = setup();
  cart.addItem('p1', 2);
  cart.updateQuantity('p1', 5);

  assert.equal(cart.getItem('p1').quantity, 5);
});

test('removes products from a cart', () => {
  const { cart } = setup();
  cart.addItem('p1', 2);
  cart.addItem('p2', 1);
  cart.removeItem('p1');

  assert.equal(cart.getItem('p1'), undefined);
