'use strict';

const { ValidationError, NotFoundError } = require('./errors');

class Cart {
  constructor() {
    this.items = new Map();
  }

  addProduct(product, quantity = 1) {
    if (!product || typeof product !== 'object' || !product.id) {
      throw new ValidationError('Product does not exist');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }

    const existing = this.items.get(product.id);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.set(product.id, {
        product,
        quantity,
      });
    }
    return this;
  }

  updateQuantity(productId, quantity) {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }
    const item = this.items.get(productId);
    if (!item) {
      throw new NotFoundError(`Product ${productId} is not in the cart`);
    }
    item.quantity = quantity;
    return this;
  }

  removeProduct(productId) {
    if (!this.items.has(productId)) {
      throw new NotFoundError(`Product ${productId} is not in the cart`);
    }
    this.items.delete(productId);
    return this;
  }

  getItems() {
    return Array.from(this.items.values()).map((item) => ({
      product: item.product,
      quantity: item.quantity,
    }));
  }

  getItem(productId) {
    const item = this.items.get(productId);
    return item ? { product: item.product, quantity: item.quantity } : undefined;
  }

  isEmpty() {
    return this.items.size === 0;
  }

  clear() {
    this.items.clear();
    return this;
  }

  subtotal() {
    let total = 0;
    for (const item of this.items.values()) {
      total += item.product.price * item.quantity;
    }
    return total;
  }

  total() {
    return this.subtotal();
  }
}

function createCart() {
  return new Cart();
}

module.exports = {
  Cart,
  createCart,
};

const { ValidationError, DuplicateProductError, ProductNotFoundError } = require('./errors');

class Catalog {
  constructor() {
    this.products = new Map();
  }

  createProduct({ id, name, description, price, quantity }) {
    if (!id || typeof id !== 'string' || id.trim() === '') {
      throw new ValidationError('Product ID is required and must be a non-empty string');
    }

    if (!name || typeof name !== 'string' || name.trim() === '') {
      throw new ValidationError('Product name is required and must be a non-empty string');
    }

    if (description === undefined || description === null) {
      description = '';
    }

    if (typeof description !== 'string') {
      throw new ValidationError('Product description must be a string');
    }

    if (typeof price !== 'number' || !Number.isFinite(price) || price < 0) {
      throw new ValidationError('Product price must be a non-negative finite number');
    }

    if (typeof quantity !== 'number' || !Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError('Product quantity must be a non-negative integer');
    }

    if (this.products.has(id)) {
      throw new DuplicateProductError(`Product with ID '${id}' already exists`);
    }

    const product = {
      id,
      name,
      description,
      price,
      quantity
    };

    this.products.set(id, product);
    return { ...product };
  }

  getProduct(id) {
    const product = this.products.get(id);
    if (!product) {
      throw new ProductNotFoundError(`Product with ID '${id}' not found`);
    }
    return { ...product };
  }

  listProducts() {
    return Array.from(this.products.values()).map(product => ({ ...product }));
  }

  updateProduct(id, updates) {
    const product = this.products.get(id);
    if (!product) {
      throw new ProductNotFoundError(`Product with ID '${id}' not found`);
    }

    const updated = { ...product };

    if (updates.name !== undefined) {
      if (typeof updates.name !== 'string' || updates.name.trim() === '') {
        throw new ValidationError('Product name must be a non-empty string');
      }
      updated.name = updates.name;
    }

    if (updates.description !== undefined) {
      if (typeof updates.description !== 'string') {
        throw new ValidationError('Product description must be a string');
      }
      updated.description = updates.description;
    }

    if (updates.price !== undefined) {
      if (typeof updates.price !== 'number' || !Number.isFinite(updates.price) || updates.price < 0) {
        throw new ValidationError('Product price must be a non-negative finite number');
      }
      updated.price = updates.price;
    }

    if (updates.quantity !== undefined) {
      if (typeof updates.quantity !== 'number' || !Number.isInteger(updates.quantity) || updates.quantity < 0) {
        throw new ValidationError('Product quantity must be a non-negative integer');
      }
      updated.quantity = updates.quantity;
    }

    this.products.set(id, updated);
    return { ...updated };
  }
}

function createCatalog() {
  return new Catalog();
}

module.exports = { Catalog, createCatalog };

const { InsufficientInventoryError, InvalidStateError } = require('./errors');

class CheckoutService {
  constructor(catalog, inventoryManager, orderManager) {
    this.catalog = catalog;
    this.inventoryManager = inventoryManager;
    this.orderManager = orderManager;
  }

  checkout(cart) {
    if (!cart || cart.isEmpty()) {
      throw new InvalidStateError('Cannot checkout an empty cart');
    }

    // Validate all items exist in catalog
    for (const item of cart.getItems()) {
      const product = this.catalog.getProduct(item.product.id);
      if (!product) {
        throw new InvalidStateError(`Product ${item.product.id} not found in catalog`);
      }
    }

    // Check inventory availability for entire cart
    if (!this.inventoryManager.checkCart(cart)) {
      throw new InsufficientInventoryError('Insufficient inventory for checkout');
    }

    // Deduct inventory
    for (const item of cart.getItems()) {
      this.inventoryManager.deduct(item.product.id, item.quantity);
    }

    // Create order
    const order = this.orderManager.createOrder({
      items: cart.getItems().map(item => ({
        productId: item.product.id,
        name: item.product.name,
        price: item.product.price,
        quantity: item.quantity,
        lineTotal: item.product.price * item.quantity
      })),
      total: cart.total(),
      timestamp: new Date()
    });

    // Clear cart after successful checkout
    cart.clear();

    return order;
  }
}

function createCheckoutService(catalog, inventoryManager, orderManager) {
  return new CheckoutService(catalog, inventoryManager, orderManager);
}

module.exports = { CheckoutService, createCheckoutService };

'use strict';

class OrderFlowError extends Error {
  constructor(message, code = 'ORDERFLOW_ERROR') {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends OrderFlowError {
  constructor(message) {
    super(message, 'VALIDATION_ERROR');
  }
}

class NotFoundError extends OrderFlowError {
  constructor(message) {
    super(message, 'NOT_FOUND');
  }
}

class DuplicateIdError extends OrderFlowError {
  constructor(message) {
    super(message, 'DUPLICATE_ID');
  }
}

class DuplicateProductError extends DuplicateIdError {
  constructor(message) {
    super(message);
  }
}

class ProductNotFoundError extends NotFoundError {
  constructor(message) {
    super(message);
  }
}

class InsufficientInventoryError extends OrderFlowError {
  constructor(message) {
    super(message, 'INSUFFICIENT_INVENTORY');
  }
}

class InvalidStateError extends OrderFlowError {
  constructor(message) {
    super(message, 'INVALID_STATE');
  }
}

module.exports = {
  OrderFlowError,
  ValidationError,
  NotFoundError,
  DuplicateIdError,
  DuplicateProductError,
  ProductNotFoundError,
  InsufficientInventoryError,
  InvalidStateError,
};

'use strict';

const { InsufficientInventoryError, NotFoundError, ValidationError } = require('./errors');

class InventoryManager {
  constructor(catalog) {
    this.catalog = catalog;
  }

  checkAvailability(productId, quantity) {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }
    const product = this.catalog.getProduct(productId);
    if (!product) {
      throw new NotFoundError(`Product ${productId} does not exist`);
    }
    return product.quantity >= quantity;
  }

  checkCart(cart) {
    for (const item of cart.getItems()) {
      this.checkAvailability(item.product.id, item.quantity);
    }
    return true;
  }

  deduct(productId, quantity) {
    this.checkAvailability(productId, quantity);
    const product = this.catalog.getProduct(productId);
    product.quantity -= quantity;
    return product.quantity;
  }

  restore(productId, quantity) {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError('Quantity must be a positive integer');
    }
    const product = this.catalog.getProduct(productId);
    if (!product) {
      throw new NotFoundError(`Product ${productId} does not exist`);
    }
    product.quantity += quantity;
    return product.quantity;
  }

  getRemaining(productId) {
    const product = this.catalog.getProduct(productId);
    if (!product) {
      throw new NotFoundError(`Product ${productId} does not exist`);
    }
    return product.quantity;
  }

  getInventoryReport() {
    return this.catalog.listProducts().map((product) => ({
      id: product.id,
      name: product.name,
      quantity: product.quantity,
    }));
  }
}

function createInventoryManager(catalog) {
  return new InventoryManager(catalog);
}

module.exports = {
  InventoryManager,
  createInventoryManager,
};

'use strict';

const { InvalidStateError, NotFoundError } = require('./errors');

const ORDER_STATUS = {
  COMPLETED: 'completed',
  CANCELLED: 'cancelled',
};

class OrderManager {
  constructor() {
    this.orders = new Map();
    this.nextId = 1;
  }

  createOrder({ items, total, timestamp = new Date(), status = ORDER_STATUS.COMPLETED }) {
    const id = this._generateOrderId();
    const order = {
      id,
      items: items.map((item) => ({
        productId: item.product?.id || item.productId,
        name: item.product?.name || item.name,
        price: item.product?.price || item.price,
        quantity: item.quantity,
      })),

      total,
      timestamp,
      status,
    };
    this.orders.set(id, order);
    return order;
  }

  getOrder(id) {
    const order = this.orders.get(id);
    if (!order) {
      throw new NotFoundError(`Order ${id} does not exist`);
    }
    return order;
  }

  cancelOrder(id) {
    const order = this.getOrder(id);
    if (order.status === ORDER_STATUS.CANCELLED) {
      throw new InvalidStateError(`Order ${id} is already cancelled`);
    }
    order.status = ORDER_STATUS.CANCELLED;
    return order;
  }

  listOrders() {
    return Array.from(this.orders.values());
  }

  _generateOrderId() {
    const id = `ORD-${String(this.nextId).padStart(4, '0')}`;
    this.nextId += 1;
    return id;
  }

  _generateOrderId() {
    const id = `ORD-${String(this.nextId).padStart(4, '0')}`;
    this.nextId += 1;
    return id;
  }
}

function createOrderManager() {
  return new OrderManager();
}

module.exports = {
  OrderManager,
  createOrderManager,
  ORDER_STATUS,
};

'use strict';

const { ORDER_STATUS } = require('./orders');

class Reports {
  constructor(orderManager, inventoryManager) {
    this.orderManager = orderManager;
    this.inventoryManager = inventoryManager;
  }

  getTotalSales() {
    return this.orderManager.listOrders()
      .filter(order => order.status === ORDER_STATUS.COMPLETED)
      .reduce((sum, order) => sum + order.total, 0);
  }

  getOrderCounts() {
    const orders = this.orderManager.listOrders();
    return {
      completed: orders.filter(order => order.status === ORDER_STATUS.COMPLETED).length,
      cancelled: orders.filter(order => order.status === ORDER_STATUS.CANCELLED).length,
      total: orders.length
    };
  }

  getBestSellingProducts() {
    const sales = new Map();
    for (const order of this.orderManager.listOrders()) {
      if (order.status !== ORDER_STATUS.COMPLETED) continue;
      for (const item of order.items) {
        const current = sales.get(item.productId) || { productId: item.productId, quantity: 0 };
        current.quantity += item.quantity;
        sales.set(item.productId, current);
      }
    }
    return Array.from(sales.values()).sort((a, b) => b.quantity - a.quantity);
  }

  getInventoryReport() {
    return this.inventoryManager.getInventoryReport();
  }

  getSalesReport() {
    return {
      totalSales: this.getTotalSales(),
      orderCounts: this.getOrderCounts(),
      bestSellingProducts: this.getBestSellingProducts(),
      inventory: this.getInventoryReport()
    };
  }
}

function createReports(orderManager, inventoryManager) {
  return new Reports(orderManager, inventoryManager);
}

module.exports = { Reports, createReports };

