exports.createCart = function(catalogRef) {
  const items = {};
  let catalog = catalogRef || null;

  return {
    addItem: function(productId, quantity) {
      items[productId] = (items[productId] || 0) + quantity;
      return items[productId];
    },
    removeItem: function(productId) {
      delete items[productId];
      return true;
    },
    updateQuantity: function(productId, quantity) {
      if (quantity <= 0) {
        delete items[productId];
      } else {
        items[productId] = quantity;
      }
      return items[productId] || 0;
    },
    getItems: function() {
      return Object.entries(items).map(([productId, quantity]) => ({
        productId: Number(productId),
        quantity
      }));
    },
    getTotal: function() {
      if (!catalog) {
        return 0;
      }
      return Object.entries(items).reduce((sum, [productId, quantity]) => {
        const product = catalog.getProduct(Number(productId));
        if (!product) {
          throw new Error('Product not found');
        }
        return sum + product.price * quantity;
      }, 0);
    },
    setCatalog: function(catalogRef) {
      catalog = catalogRef;
    },
    getCatalog: function() {
      return catalog;
    }
  };
};

exports.createCatalog = function() {
  const products = [];
  let nextId = 1;

  return {
    listProducts: function() {
      return [...products];
    },
    addProduct: function({ name, price, sku }) {
      const product = {
        id: nextId++,
        name,
        price,
        sku
      };
      products.push(product);
      return product;
    },
    getProduct: function(id) {
      return products.find(p => p.id === id);
    },
    getProductBySku: function(sku) {
      return products.find(p => p.sku === sku);
    },
    updateProduct: function(id, updates) {
      const product = products.find(p => p.id === id);
      if (!product) return null;
      Object.assign(product, updates);
      return product;
    },
    removeProduct: function(id) {
      const index = products.findIndex(p => p.id === id);
      if (index === -1) return false;
      products.splice(index, 1);
      return true;
    }
  };
};

const errors = require('./errors');

exports.createCheckout = function({ catalog, orders, inventory }) {
  return {
    process: function(cart) {
      const items = cart.getItems();
      if (items.length === 0) {
        throw new errors.InvalidOrderError('Cart is empty');
      }

      for (const item of items) {
        const product = catalog.getProduct(item.productId);
        if (!product) {
          throw new errors.ProductNotFoundError(`Product ${item.productId} not found`);
        }
        if (!inventory.isAvailable(item.productId, item.quantity)) {
          throw new errors.InsufficientStockError(`Insufficient stock for product ${item.productId}`);
        }
      }

      for (const item of items) {
        inventory.removeStock(item.productId, item.quantity);
      }

      const order = orders.createOrder(items);
      orders.updateOrderStatus(order.id, 'completed');
      return order;
    }
  };
};

exports.InsufficientStockError = class extends Error {
  constructor(message = 'Insufficient stock') {
    super(message);
    this.name = 'InsufficientStockError';
  }
};

exports.ProductNotFoundError = class extends Error {
  constructor(message = 'Product not found') {
    super(message);
    this.name = 'ProductNotFoundError';
  }
};

exports.InvalidOrderError = class extends Error {
  constructor(message = 'Invalid order') {
    super(message);
    this.name = 'InvalidOrderError';
  }
};

exports.createInventory = function() {
  const stock = {};

  return {
    getStockLevels: function() {
      return { ...stock };
    },
    addStock: function(productId, quantity) {
      stock[productId] = (stock[productId] || 0) + quantity;
      return stock[productId];
    },
    removeStock: function(productId, quantity) {
      const current = stock[productId] || 0;
      if (current < quantity) {
        throw new Error('Insufficient stock');
      }
      stock[productId] = current - quantity;
      return true;
    },
    getStock: function(productId) {
      return stock[productId] || 0;
    },
    isAvailable: function(productId, quantity) {
      return (stock[productId] || 0) >= quantity;
    }
  };
};

exports.createOrders = function() {
  const orders = [];
  let nextId = 1;

  return {
    listOrders: function() {
      return [...orders];
    },
    createOrder: function(items) {
      const order = {
        id: nextId++,
        items,
        status: 'pending'
      };
      orders.push(order);
      return order;
    },
    getOrder: function(id) {
      return orders.find(o => o.id === id);
    },
    updateOrderStatus: function(id, status) {
      const order = orders.find(o => o.id === id);
      if (!order) return null;
      order.status = status;
      return order;
    },
    cancelOrder: function(id) {
      const order = orders.find(o => o.id === id);
      if (!order) return null;
      order.status = 'cancelled';
      return order;
    }
  };
};

const errors = require('../src/errors');

exports.createReports = function({ orders, catalog }) {
  return {
    generateSalesReport: function() {
      const completedOrders = orders.listOrders().filter(order => order.status === 'completed');
      const totalRevenue = completedOrders.reduce((sum, order) => {
        return sum + order.items.reduce((itemSum, item) => {
          const product = catalog.getProduct(item.productId);
          return itemSum + (product.price * item.quantity);
        }, 0);
      }, 0);
      return {
        totalRevenue,
        totalOrders: completedOrders.length
      };
    }
  };
};

