    expect(found.name).toBe('Keyboard');
  });

  test('update product', () => {
    const product = catalog.addProduct({ name: 'Monitor', price: 199.99, sku: 'MON001' });
    const updated = catalog.updateProduct(product.id, { price: 179.99 });
    expect(updated.price).toBe(179.99);
