    expect(removed).toBe(true);
    expect(catalog.listProducts()).toHaveLength(0);
  });

  test('inventory starts empty', () => {
    expect(inventory.getStockLevels()).toEqual({});
  });

  test('add stock', () => {
    const product = catalog.addProduct({ name: 'Chair', price: 89.99, sku: 'CHR001' });
    inventory.addStock(product.id, 10);
    expect(inventory.getStock(product.id)).toBe(10);
  });

  test('remove stock', () => {
    const product = catalog.addProduct({ name: 'Table', price: 149.99, sku: 'TBL001' });
    inventory.addStock(product.id, 5);
    const result = inventory.removeStock(product.id, 3);
    expect(result).toBe(true);
    expect(inventory.getStock(product.id)).toBe(2);
