  test('full workflow: catalog -> inventory -> cart -> checkout -> reports', () => {
    const { createCart } = require('../src/cart');
    const { createCheckout } = require('../src/checkout');
    const { createReports } = require('../src/reports');
    const cart = createCart();
    const checkout = createCheckout({ catalog, orders, inventory });
    const reports = createReports({ orders, catalog });

    const product1 = catalog.addProduct({ name: 'Product A', price: 100, sku: 'PRDA' });
    const product2 = catalog.addProduct({ name: 'Product B', price: 50, sku: 'PRDB' });
    inventory.addStock(product1.id, 10);
    inventory.addStock(product2.id, 20);

    cart.addItem(product1.id, 2);
    cart.addItem(product2.id, 4);
    expect(cart.getTotal()).toBe(400);

    const order = checkout.process(cart);
    expect(order.status).toBe('completed');
    expect(inventory.getStock(product1.id)).toBe(8);
    expect(inventory.getStock(product2.id)).toBe(16);

    const report = reports.generateSalesReport();
    expect(report.totalRevenue).toBe(400);
    expect(report.totalOrders).toBe(1);
  });
